<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\{Auth,Controller,Csrf,Database}; use App\Models\{Analytics,Category,Post,Setting,Video};
final class AdminController extends Controller
{
    public function login(): void { if(Auth::check())$this->redirect('/admin'); $this->render('admin/login',['title'=>'Acceso editorial','error'=>null],'auth'); }
    public function authenticate(): void { Csrf::verify(); if(Auth::attempt(trim($_POST['email']??''),$_POST['password']??''))$this->redirect('/admin'); $this->render('admin/login',['title'=>'Acceso editorial','error'=>'Correo o contraseña incorrectos.'],'auth'); }
    public function logout(): void { Csrf::verify(); Auth::logout(); $this->redirect('/'); }
    public function dashboard(): void { Auth::requireLogin(); $db=Database::connection(); $stats=['posts'=>(int)$db->query('SELECT COUNT(*) FROM posts')->fetchColumn(),'published'=>(int)$db->query("SELECT COUNT(*) FROM posts WHERE status='published'")->fetchColumn(),'categories'=>(int)$db->query('SELECT COUNT(*) FROM categories')->fetchColumn()]; $this->render('admin/dashboard',['title'=>'Panel editorial','stats'=>$stats,'analytics'=>Analytics::dashboard(),'posts'=>array_slice(Post::allAdmin(),0,6)],'admin'); }
    public function posts(): void { Auth::requireLogin(); $this->render('admin/posts/index',['title'=>'Noticias','posts'=>Post::allAdmin()],'admin'); }
    public function events(): void { Auth::requireLogin(); $parent=Category::findBySlug('eventos'); $this->render('admin/events/index',['title'=>'Agenda y eventos','posts'=>$parent?Post::allAdmin((int)$parent['id']):[],'resourcePath'=>'/admin/events'],'admin'); }
    public function createEvent(): void { Auth::requireLogin(); $this->eventForm(null); }
    public function editEvent(int $id): void { Auth::requireLogin(); $post=Post::find($id); if(!$post||!$this->isEventCategory((int)$post['category_id'])){http_response_code(404);$this->redirect('/admin/events');} $this->eventForm($post); }
    private function eventForm(?array $post, ?string $error=null): void { $this->render('admin/posts/form',['title'=>$post?'Editar evento':'Nuevo evento','post'=>$post,'categories'=>Category::childrenOf('eventos'),'error'=>$error,'resourcePath'=>'/admin/events','entityLabel'=>'evento'],'admin'); }
    public function storeEvent(?int $id=null): void { Auth::requireLogin(); Csrf::verify(); $title=trim($_POST['title']??'');$body=trim($_POST['body']??'');$categoryId=(int)($_POST['category_id']??0);if($title===''||$body===''||!$this->isEventCategory($categoryId)){$this->eventForm(array_merge($_POST,['id'=>$id]),'El título, el contenido y una categoría de eventos son obligatorios.');return;}$slug=$this->slug($_POST['slug']?:$title);$image=trim($_POST['image']??'');if(isset($_FILES['upload'])&&$_FILES['upload']['error']===UPLOAD_ERR_OK){$image=$this->upload($_FILES['upload']);}Post::save(['category_id'=>$categoryId,'user_id'=>(int)Auth::user()['id'],'title'=>$title,'slug'=>$slug,'excerpt'=>trim($_POST['excerpt']??''),'body'=>$this->editorHtml($body),'tags'=>trim($_POST['tags']??''),'image'=>$image,'status'=>in_array($_POST['status']??'draft',['draft','published'],true)?$_POST['status']:'draft','featured'=>0,'published_at'=>str_replace('T',' ',$_POST['published_at']??date('Y-m-d H:i')).':00'],$id);$_SESSION['flash']='Evento guardado correctamente.';$this->redirect('/admin/events'); }
    public function destroyEvent(int $id): void { Auth::requireLogin();Csrf::verify();$post=Post::find($id);if($post&&$this->isEventCategory((int)$post['category_id']))Post::delete($id);$_SESSION['flash']='Evento eliminado.';$this->redirect('/admin/events'); }
    private function isEventCategory(int $categoryId): bool { foreach(Category::childrenOf('eventos') as $category){if((int)$category['id']===$categoryId)return true;}return false; }
    public function videos(): void { Auth::requireLogin(); $this->render('admin/videos/index',['title'=>'Pulso Angelino TV','videos'=>Video::allAdmin()],'admin'); }
    public function createVideo(): void { Auth::requireLogin(); $this->videoForm(null); }
    public function editVideo(int $id): void { Auth::requireLogin(); $video=Video::find($id); if(!$video){http_response_code(404);$this->redirect('/admin/videos');} $this->videoForm($video); }
    private function videoForm(?array $video, ?string $error=null): void { $this->render('admin/videos/form',['title'=>$video?'Editar video':'Nuevo video','video'=>$video,'error'=>$error],'admin'); }
    public function saveVideo(?int $id=null): void { Auth::requireLogin(); Csrf::verify(); $title=trim($_POST['title']??'');$videoUrl=trim($_POST['video_url']??'');$cover=trim($_POST['cover_image']??'');if(isset($_FILES['upload'])&&$_FILES['upload']['error']===UPLOAD_ERR_OK){$cover=$this->upload($_FILES['upload']);}$video=array_merge($_POST,['id'=>$id,'cover_image'=>$cover]);$scheme=strtolower((string)parse_url($videoUrl,PHP_URL_SCHEME));if($title===''||!filter_var($videoUrl,FILTER_VALIDATE_URL)||!in_array($scheme,['http','https'],true)){$this->videoForm($video,'El título y una URL de video válida (http o https) son obligatorios.');return;}if($cover===''){$this->videoForm($video,'Debes agregar una imagen de portada.');return;}Video::save(['title'=>$title,'description'=>$this->editorHtml($_POST['description']??''),'commune'=>in_array($_POST['commune']??'',Video::COMMUNES,true)?$_POST['commune']:Video::COMMUNES[0],'format'=>in_array($_POST['format']??'',Video::FORMATS,true)?$_POST['format']:Video::FORMATS[0],'cover_image'=>$cover,'video_url'=>$videoUrl,'status'=>in_array($_POST['status']??'draft',['draft','published'],true)?$_POST['status']:'draft','published_at'=>str_replace('T',' ',$_POST['published_at']??date('Y-m-d H:i')).':00'],$id);$_SESSION['flash']='Video guardado correctamente.';$this->redirect('/admin/videos'); }
    public function destroyVideo(int $id): void { Auth::requireLogin();Csrf::verify();Video::delete($id);$_SESSION['flash']='Video eliminado.';$this->redirect('/admin/videos'); }
    public function weather(): void { Auth::requireLogin(); $this->render('admin/weather',['title'=>'Configuración del tiempo','weather'=>Setting::weather(),'error'=>null],'admin'); }
    public function saveWeather(): void { Auth::requireLogin(); Csrf::verify(); $latitude=filter_var($_POST['weather_fallback_latitude']??'',FILTER_VALIDATE_FLOAT); $longitude=filter_var($_POST['weather_fallback_longitude']??'',FILTER_VALIDATE_FLOAT); if($latitude===false||$longitude===false||$latitude < -90||$latitude > 90||$longitude < -180||$longitude > 180){$this->render('admin/weather',['title'=>'Configuración del tiempo','weather'=>$_POST,'error'=>'Ingresa coordenadas válidas para la ubicación de respaldo.'],'admin');return;} Setting::saveWeather(['weather_enabled'=>isset($_POST['weather_enabled'])?'1':'0','weather_title'=>trim($_POST['weather_title']??'')?:'El tiempo en tu comuna','weather_fallback_name'=>trim($_POST['weather_fallback_name']??'')?:'Los Ángeles','weather_fallback_latitude'=>(string)$latitude,'weather_fallback_longitude'=>(string)$longitude]); $_SESSION['flash']='Configuración del tiempo guardada.';$this->redirect('/admin/weather'); }
    public function create(): void { Auth::requireLogin(); $this->form(null); }
    public function edit(int $id): void { Auth::requireLogin(); $this->form(Post::find($id)); }
    private function form(?array $post): void { $this->render('admin/posts/form',['title'=>$post?'Editar noticia':'Nueva noticia','post'=>$post,'categories'=>Category::all(),'error'=>null],'admin'); }
    public function store(?int $id=null): void { Auth::requireLogin(); Csrf::verify(); $title=trim($_POST['title']??''); $body=trim($_POST['body']??''); if($title===''||$body===''){ $this->render('admin/posts/form',['title'=>$id?'Editar noticia':'Nueva noticia','post'=>array_merge($_POST,['id'=>$id]),'categories'=>Category::all(),'error'=>'El título y el contenido son obligatorios.'],'admin');return;} $slug=$this->slug($_POST['slug']?:$title); $image=trim($_POST['image']??''); if(isset($_FILES['upload'])&&$_FILES['upload']['error']===UPLOAD_ERR_OK){$image=$this->upload($_FILES['upload']);} Post::save(['category_id'=>(int)$_POST['category_id'],'user_id'=>(int)Auth::user()['id'],'title'=>$title,'slug'=>$slug,'excerpt'=>trim($_POST['excerpt']??''),'body'=>$this->editorHtml($body),'tags'=>trim($_POST['tags']??''),'image'=>$image,'status'=>in_array($_POST['status']??'draft',['draft','published'],true)?$_POST['status']:'draft','featured'=>isset($_POST['featured'])?1:0,'published_at'=>str_replace('T',' ',$_POST['published_at']??date('Y-m-d H:i')).':00'],$id); $_SESSION['flash']='Noticia guardada correctamente.';$this->redirect('/admin/posts'); }
    public function destroy(int $id): void { Auth::requireLogin();Csrf::verify();Post::delete($id);$_SESSION['flash']='Noticia eliminada.';$this->redirect('/admin/posts'); }
    private function editorHtml(string $html): string { $html=strip_tags($html,'<p><br><strong><b><em><i><u><h2><h3><ul><ol><li><blockquote><a>'); $html=preg_replace('/\s+on[a-z]+\s*=\s*(["\']).*?\1/iu','',$html)??$html; $html=preg_replace('/<(?!a\b)([a-z0-9]+)\s+[^>]*>/iu','<$1>',$html)??$html; $html=preg_replace_callback('/<a\s+([^>]*)>/iu',function(array $match):string{preg_match('/href\s*=\s*(["\'])(.*?)\1/iu',$match[1],$href);$url=html_entity_decode($href[2]??'');return preg_match('#^(https?://|mailto:)#i',$url)?'<a href="'.e($url).'" target="_blank" rel="noopener">':'<a>';},$html)??$html; return trim($html); }
    private function slug(string $text): string { $text=iconv('UTF-8','ASCII//TRANSLIT',$text)?:$text;return trim(preg_replace('/[^a-z0-9]+/','-',strtolower($text))??'','-'); }
    private function upload(array $file): string { $mime=(new \finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$types=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($types[$mime])||$file['size']>5_000_000)throw new \RuntimeException('Imagen inválida (JPG, PNG o WebP; máximo 5 MB).');$name=bin2hex(random_bytes(12)).'.'.$types[$mime];move_uploaded_file($file['tmp_name'],dirname(__DIR__,2).'/public/uploads/'.$name);return 'uploads/'.$name; }
}
